tasks.reference_answer:
def binary_search(nums, target):
    left, right = 0, len(nums) - 1
    while left <= right:
        mid = (left + right) // 2
        if nums[mid] == target:
            return mid
        if nums[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return -1

import json
def parse_jsonl(text):
    out = []
    for line in text.split("\n"):
        line = line.strip()
        if not line:
            continue
        out.append(json.loads(line))
    return out

