def dedupe(items):
    seen = set()
    out = []
    for item in items:
        if item not in seen:
            seen.add(item)
            out.append(item)
    return out

from collections import defaultdict
def group_by_first(words):
    groups = defaultdict(list)
    for word in words:
        key = word[0].lower() if word else "_"
        groups[key].append(word)
    return dict(groups)

def safe_divide(a, b):
    if b == 0:
        return None
    return round(a / b, 2)

